#include <stdio.h>

/* teste do desafio de MODULO a-portaria-do-clube — counter_protocol (03-tdd 3.9.3).
   Cada cenario escreve num arquivo o que a pessoa digitaria, aponta o stdin
   para esse arquivo (freopen) e captura o stdout no proprio teste. Os nomes
   dos temporarios sao POR CENARIO. Nunca ha fclose de stdin/stdout — so fflush. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void aPortariaDoClube(void);

SM_TEST(adulto_inteira_a_tarde) {
    /* caso comum: adulto com inteira a tarde entra */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "20 1 14\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    aPortariaDoClube();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[120] = "(nada impresso)";
    fgets(linha, 120, f);
    checa_str("a idade digitada", linha, "idade: 20\n",
              "a primeira linha devolve a idade que foi digitada");
    fgets(linha, 120, f);
    checa_str("o preco do ingresso", linha, "preco: 60\n",
              "o preco sai do painel de botoes: 1 vale 60, 2 vale 30, 3 vale 0, qualquer outro vale -1");
    fgets(linha, 120, f);
    checa_str("o sinalizador de maior", linha, "maior: 1\n",
              "a comparacao com 18 ja vale 0 ou 1");
    fgets(linha, 120, f);
    checa_str("o turno da chegada", linha, "turno: 2\n",
              "a cascata decide a faixa: ate 11, ate 17, ou o resto");
    fgets(linha, 120, f);
    checa_str("a decisao de entrar", linha, "entra: 1\n",
              "a decisao final compoe o E, o OU e a negacao");
    char fim[120] = "(nada impresso)";
    fgets(fim, 120, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a decisao termina na quinta linha");
    fclose(f);
}

