#include <stdio.h>

void aPortariaDoClube(void) {
    int idade = 0;
    int tipo = 0;
    int hora = 0;
    scanf("%d %d %d", &idade, &tipo, &hora);

    int preco = -1;
    switch (tipo) {
        case 1:
            preco = 60;
            break;
        case 2:
            preco = 30;
            break;
        case 3:
            preco = 0;
            break;
        default:
            preco = -1;
            break;
    }

    int maior = idade >= 18;

    int turno = 3;
    if (hora <= 11) {
        turno = 1;
    } else if (hora <= 17) {
        turno = 2;
    } else {
        turno = 3;
    }

    int valido = preco != -1;
    int cortesia = tipo == 3;
    int noturnoProibido = !maior && turno == 3;
    int entra = valido && (maior || cortesia) && !noturnoProibido;

    printf("idade: %d\n", idade);
    printf("preco: %d\n", preco);
    printf("maior: %d\n", maior);
    printf("turno: %d\n", turno);
    printf("entra: %d\n", entra);
}
